  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Computes the final booking price after applying eligible membership discounts.
   * Algorithm:
   * 1. If customer or bookingTime is null, return price.
   * 2. If customer or customer.membershipPackage is null, return price.
   * 3. Check whether membershipPackage has Award.DISCOUNTS.
   *    - If not, return price.
   * 4. Determine whether bookingTime is at least 24 hours before this trip’s departure date/time.
   * 5. If not eligible, return price.
   * 6. Compute discountedPrice = price * 0.8.
   * 7. Round the result to one decimal place.
   * 8. Return discountedPrice.
   * Related Features:
   * - price
   * - departureDate
   * - departureTime
   * Related Classes:
   * - Customer
   * - MembershipPackage
   * - Award
   * - EDate
   * Input:
   * - customer: Customer, booking owner; must be non-null for discount evaluation.
   * - bookingTime: String, the booking timestamp used for the 24-hour rule.
   * Output:
   * - double.
   * - Final price after discount, rounded to one decimal place.
   * - If any condition is invalid or missing, returns the original trip price.
   * Pre-condition:
   * - price is initialized and non-negative.
   * - departureDate and departureTime are valid.
   * - bookingTime uses a supported date-time format.
   * Post-condition:
   * - No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null)
    {
      return price;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.DISCOUNTS))
    {
      return price;
    }
    if (departureDate == null || departureTime == null)
    {
      return price;
    }

    try
    {
      String datePart = departureDate.toString();
      java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm");
      sdf.setLenient(false);

      java.util.Date bookingDateTime = sdf.parse(bookingTime);
      java.util.Date departureDateTime = sdf.parse(datePart + " " + departureTime);

      long diffMillis = departureDateTime.getTime() - bookingDateTime.getTime();
      if (diffMillis < 24L * 60L * 60L * 1000L)
      {
        return price;
      }

      double discountedPrice = price * 0.8;
      return Math.round(discountedPrice * 10.0) / 10.0;
    }
    catch (Exception e)
    {
      return price;
    }
    
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Computes the reward points earned by a customer from bookings on this trip during a given month.
   * Algorithm:
   * 1. If customer or currentMonth is null, return 0.
   * 2. If customer.membershipPackage is null, return 0.
   * 3. If customer.membershipPackage does not contain Award.POINTS, return 0.
   * 4. Initialize total = 0.
   * 5. For each booking in bookings:
   *    - If booking.customer equals the given customer and booking.isInMonth(currentMonth) is true,
   *      add booking.numberOfSeats * 5 to total.
   * 6. Return total.
   * Related Features:
   * - bookings
   * Related Classes:
   * - Booking
   * - Customer
   * - MembershipPackage
   * - Award
   * Input:
   * - customer: Customer, the customer whose points are calculated; must be non-null.
   * - currentMonth: String, the target month identifier, typically in "YYYY-MM" format.
   * Output:
   * - int.
   * - Total points earned from eligible bookings on this trip in the specified month.
   * - Returns 0 for invalid input or unsupported reward.
   * Pre-condition:
   * - bookings collection is readable.
   * - currentMonth is a supported month format.
   * Post-condition:
   * - No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null)
    {
      return 0;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.POINTS))
    {
      return 0;
    }

    int total = 0;
    if (bookings != null)
    {
      for (Booking booking : bookings)
      {
        if (booking != null && customer.equals(booking.getCustomer()) && booking.isInMonth(currentMonth))
        {
          total += booking.getNumberOfSeats() * 5;
        }
      }
    }
    return total;
    
  }

