      java.util.Date proposedDeparture = sdf.parse(newDepartureTime);
      java.util.Date proposedArrival = sdf.parse(newArrivalTime);

      long thisStart = thisDeparture.getTime();
      long thisEnd = thisArrival.getTime();
      long proposedStart = proposedDeparture.getTime();
      long proposedEnd = proposedArrival.getTime();

